 1| /**
 2|  * apply-coupon: takes a coupon off the subtotal.
 3|  *
 4|  * A percentage coupon is rounded to the cent; a fixed coupon never takes off
 5|  * more than the subtotal. An unknown or missing code gives no discount.
 6|  * Example: `SPRING10` on 200.00 → `discount = 20`.
 7|  */
 8| import { COUPONS } from '../../data/coupons.mjs';
 9| import { roundCents } from '../../money.mjs';
10| 
11| export const purpose = 'Work out the coupon discount on the subtotal.';
12| 
13| /** @param {any} scope */
14| export function run(scope) {
15|   const coupon = COUPONS[scope.couponCode];
16|   if (!coupon) {
17|     scope.discount = 0;
18|     return;
19|   }
20|   scope.discount = coupon.percent
21|     ? roundCents((scope.subtotal * coupon.percent) / 100)
22|     : Math.min(coupon.fixed ?? 0, scope.subtotal);
23| }
